"""Six-video-tool projection against the independent pre-recipe catalog."""

from __future__ import annotations

import json
import os
import subprocess
import sys
from copy import deepcopy
from dataclasses import replace
from pathlib import Path
from typing import Any

import pytest
from fastapi.testclient import TestClient
from test_service import FakeRuntime

from latentslate_engine import service
from latentslate_engine.recipe import ProductPolicy, exposed

# Captured from the unmodified starting implementation, never generated by tests.
ORACLE = Path(__file__).parent / "fixtures" / "catalog-ee7e883.json"
PROBES = {
    service.T2V_ID: "LTX23_T2V_POLICY",
    service.I2V_ID: "LTX23_I2V_POLICY",
    service.FLF_ID: "LTX23_FLF_POLICY",
    service.WAN_T2V_ID: "WAN2214B_T2V_POLICY",
    service.WAN_I2V_ID: "WAN2214B_I2V_POLICY",
    service.WAN_FLF_ID: "WAN2214B_FLF_POLICY",
}


def _baseline() -> list[dict[str, Any]]:
    return json.loads(ORACLE.read_text(encoding="utf-8"))["tools"]


@pytest.fixture(
    params=PROBES,
    ids=("ltx-t2v", "ltx-i2v", "ltx-flf", "wan-t2v", "wan-i2v", "wan-flf"),
)
def probe(request) -> tuple[str, ProductPolicy]:
    return request.param, getattr(service, PROBES[request.param])


def test_complete_production_catalog_matches_frozen_starting_contract() -> None:
    baseline = _baseline()
    assert service.TOOLS == baseline
    assert service._tool_definitions() == baseline
    assert service.TOOLS_BY_ID == {tool["id"]: tool for tool in baseline}


def test_production_projection_matches_frozen_inputs_and_schema(probe) -> None:
    tool_id, definition = probe
    expected = next(tool for tool in _baseline() if tool["id"] == tool_id)
    surface = definition.surface()
    projected = service.TOOLS_BY_ID[tool_id]["inputs"]
    assert projected == expected["inputs"]
    assert [item["key"] for item in surface] == [
        item["key"] for item in expected["inputs"]
    ]
    assert all(
        not item.get("nullable") and not item.get("collection") for item in surface
    )
    assert all("label" not in item and "ui" not in item for item in surface)
    assert all(item["type"] not in {"artifact", "adapter"} for item in surface)
    exposed_keys = {
        field.capability.key for field in definition.fields if field.exposed
    }
    hidden_keys = {
        cap.key for cap in definition.capabilities.capabilities
    } - exposed_keys
    assert not hidden_keys & {item["key"] for item in projected}

    # Tool identity, canvas, timing and hashing stay on the service side.
    tool = service.TOOLS_BY_ID[tool_id]
    base = {
        key: value
        for key, value in tool.items()
        if key not in {"schema_hash", "timing"}
    }
    assert tool == expected
    assert service._schema_hash(base) == expected["schema_hash"]
    assert (
        service._schema_hash({**base, "timing": tool["timing"]})
        != expected["schema_hash"]
    )


def test_semantics_feed_production_but_presentation_is_service_owned(
    probe, monkeypatch
) -> None:
    tool_id, definition = probe
    changed = replace(
        definition,
        fields=tuple(
            exposed(field.capability, default="Recipe prompt")
            if field.capability.key == "prompt"
            else exposed(field.capability, default=3.0, minimum=2.0, maximum=4.0)
            if field.capability.key == "duration_seconds"
            else field
            for field in reversed(definition.fields)
        ),
    )
    monkeypatch.setattr(service, PROBES[tool_id], changed)
    tools = service._tool_definitions()
    tool = next(item for item in tools if item["id"] == tool_id)
    assert [item["key"] for item in tool["inputs"]] == [
        item["key"] for item in changed.surface()
    ]
    projected = {item["key"]: item for item in tool["inputs"]}
    assert projected["prompt"]["default"] == "Recipe prompt"
    assert projected["prompt"]["required"] is False
    assert projected["duration_seconds"]["default"] == 3.0
    assert projected["duration_seconds"]["ui"] == {
        "min": 2.0,
        "max": 4.0,
        "step": 0.5
        if tool_id in {service.T2V_ID, service.I2V_ID, service.FLF_ID}
        else 0.25,
        "unit": "seconds",
    }
    for semantic, public in zip(changed.surface(), projected.values(), strict=True):
        assert public["key"] == semantic["key"]
        assert public["type"] == semantic["type"]
        assert public.get("role") == semantic.get("role")
        assert public.get("default") == semantic.get("default")
    surface = {item["key"]: item for item in definition.surface()}
    assert surface["seed"]["constraints"] == {"min": 0, "max": 2**64 - 1}
    assert "ui" not in projected["seed"]
    assert "max" in surface["width"]["constraints"]
    assert set(projected["width"]["ui"]) == {"min", "step"}

    baseline = next(item for item in _baseline() if item["id"] == tool_id)
    assert {
        key: value
        for key, value in tool.items()
        if key not in {"inputs", "schema_hash"}
    } == {
        key: value
        for key, value in baseline.items()
        if key not in {"inputs", "schema_hash"}
    }
    assert [item for item in tools if item["id"] != tool_id] == [
        item for item in _baseline() if item["id"] != tool_id
    ]
    assert projected["prompt"]["ui"] == {
        "multiline": True,
        "placeholder": "Describe the shot",
    }
    for item in baseline["inputs"]:
        assert projected[item["key"]]["label"] == item["label"]
    assert all(
        projected[key]["required"] is True
        for key in ("width", "height", "duration_seconds", "seed")
    )
    assert service.TOOLS == _baseline()


def test_production_projection_takes_media_labels_from_service(probe) -> None:
    _, policy = probe
    before = deepcopy(policy.surface())
    projected = service._video_policy_inputs(
        policy.surface(), {"start_image": "Service first", "end_image": "Service last"}
    )
    media = [item for item in projected if item["type"] == "image"]
    assert [item["label"] for item in media] == ["Service first", "Service last"][
        : len(media)
    ]
    assert policy.surface() == before


def test_recipe_defaults_do_not_mean_optional_wire_inputs(
    probe, tmp_path: Path
) -> None:
    tool_id, definition = probe
    surface = {item["key"]: item for item in definition.surface()}
    expected = next(tool for tool in _baseline() if tool["id"] == tool_id)
    with TestClient(
        service.create_app(home=tmp_path, token="", executor=FakeRuntime())
    ) as client:
        for key in ("width", "height", "duration_seconds", "seed"):
            assert surface[key]["required"] is False
            assert (
                surface[key]["default"]
                == {"width": 512, "height": 512, "duration_seconds": 5.0, "seed": 0}[
                    key
                ]
            )
            inputs = {
                item["key"]: item.get("default", "unused")
                for item in expected["inputs"]
            }
            del inputs[key]
            response = client.post(
                "/v1/jobs",
                json={
                    "tool_id": tool_id,
                    "schema_revision": expected["schema_revision"],
                    "schema_hash": expected["schema_hash"],
                    "inputs": inputs,
                },
            )
            assert response.status_code == 422
            assert response.json() == {
                "error": {"message": "The request is missing required inputs"}
            }


@pytest.mark.parametrize("available", (True, False))
def test_catalog_endpoint_preserves_frozen_contract(
    tmp_path: Path, available: bool
) -> None:
    runtime = FakeRuntime(
        unavailable_operations=set()
        if available
        else {service.TOOL_OPERATIONS[tool_id] for tool_id in PROBES}
    )
    expected = []
    for tool in _baseline():
        public = {**tool, "available": available or tool["id"] not in PROBES}
        if not public["available"]:
            family = (
                "LTX"
                if tool["id"] in {service.T2V_ID, service.I2V_ID, service.FLF_ID}
                else "Wan"
            )
            public["unavailable_reason"] = (
                f"Required {family} model files are not installed"
            )
        expected.append(public)
    with TestClient(
        service.create_app(home=tmp_path, token="", executor=runtime)
    ) as client:
        response = client.get("/v1/catalog")
        assert response.status_code == 200
        assert response.json() == {
            "protocol_version": "1.0",
            "engine_version": "0.1.0",
            "bundles": [],
            "tools": expected,
        }


def test_static_catalog_needs_no_configuration_or_binding() -> None:
    script = """
import builtins
import io
import json
import os
import sys
from contextlib import ExitStack
from pathlib import Path
from unittest.mock import patch
import dotenv
import fastapi
from fastapi.responses import FileResponse, JSONResponse
from latentslate_engine.recipe import Artifact, ProductPolicy, Recipe

def forbidden(*args, **kwargs):
    raise AssertionError('static catalog must not configure, inspect artifacts or bind')
dotenv.load_dotenv = forbidden
# Allow normal Python source/bytecode loading, but no application filesystem IO.
with ExitStack() as stack:
    for name in ('open', 'read_text', 'read_bytes', 'stat', 'exists', 'is_file', 'is_dir', 'resolve'):
        stack.enter_context(patch.object(Path, name, forbidden))
    for name in ('open', 'stat', 'listdir', 'scandir'):
        stack.enter_context(patch.object(os, name, forbidden))
    stack.enter_context(patch.object(builtins, 'open', forbidden))
    stack.enter_context(patch.object(io, 'open', forbidden))
    stack.enter_context(patch.object(Artifact, '__init__', forbidden))
    stack.enter_context(patch.object(ProductPolicy, 'bind', forbidden))
    stack.enter_context(patch.object(Recipe, '__post_init__', forbidden))
    from latentslate_engine import service
    assert service._tool_definitions() == service.TOOLS
    tools = service.TOOLS
assert 'torch' not in sys.modules
for name in ('latentslate_engine.ltx23.t2v', 'latentslate_engine.ltx23.i2v',
             'latentslate_engine.ltx23.flf', 'latentslate_engine.wan2214b.flf',
             'latentslate_engine.wan2214b.i2v', 'latentslate_engine.wan2214b.pipeline'):
    assert name not in sys.modules
print(json.dumps(tools))
"""
    completed = subprocess.run(
        [sys.executable, "-c", script],
        check=False,
        capture_output=True,
        text=True,
        env={
            key: value
            for key, value in os.environ.items()
            if key
            not in {
                "LATENTSLATE_ENGINE_HOME",
                "LATENTSLATE_WAN_MODEL_ROOT",
                "LATENTSLATE_KLEIN9B_VAE",
            }
        },
    )
    assert completed.returncode == 0, completed.stderr
    assert json.loads(completed.stdout) == _baseline()


def test_unconfigured_model_files_do_not_remove_catalog_tools(
    tmp_path: Path, monkeypatch
) -> None:
    monkeypatch.setattr(service, "load_dotenv", lambda *args: None)
    monkeypatch.delenv("LATENTSLATE_WAN_MODEL_ROOT", raising=False)
    monkeypatch.delenv("LATENTSLATE_KLEIN9B_VAE", raising=False)
    with TestClient(service.create_app(home=tmp_path, token="")) as client:
        tools = client.get("/v1/catalog").json()["tools"]
        assert all(tool["available"] is False for tool in tools)
        assert [
            {
                key: value
                for key, value in tool.items()
                if key not in {"available", "unavailable_reason"}
            }
            for tool in tools
        ] == _baseline()
